      SUBROUTINE REPEAT1CC     KEEPS TRACK OF REPEAT ELEMENTCC ----------------------------------------------------------------------      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC     BEGINNING OF REPEATED SECTIONC   10 IF ((NREP .EQ. 0 .AND. NDIF .EQ. 1) .OR.     1    (NREP .GT. 0 .AND. NDIF .EQ. -1)) GO TO 20      IP = IP + 1      IF (IP .LE. 0 .OR. IP .GT. 4) THEN        WRITE (NOUT,9001) IP 9001   FORMAT (' ***NESTING LEVEL TOO DEEP, IP = ',I5)        FLUSHL = .TRUE.        GO TO 40      ENDIF      IF (NDIF .EQ. 1) IC(IP) = NREP      IF (NDIF .EQ. -1) IC(IP) = 0      IS(IP) = NUM      GO TO 40CC     END OF REPEATED SECTIONC   20 IF (IP .EQ. 0 .AND. NDIF .EQ. 1) GO TO 40      IF (NDIF .EQ. -1 .AND. IC(IP) .EQ. 0) IC(IP) = NREP      IC(IP) = IC(IP) - 1      IF (IC(IP) .LE. 0) GO TO 30      NUM = IS(IP)      GO TO 40   30 IP = IP - 1      IF (IP .LT. 0 .OR. IP .GT. 4) THEN        WRITE (NOUT,9002) IP 9002   FORMAT (' *** ERROR *** REPEAT LEVEL = ',I5)        FLUSHL = .TRUE.        GO TO 40      ENDIF   40 CONTINUE      RETURN      END